insert into public.termos (termo, sinonimos, categoria, definicao, exemplo, dica, fonte)
values
  ('Above the fold', array['Acima da dobra']::text[], 'Arquitetura da Informação', 'Área de uma página visível sem rolar a tela.', 'Numa landing page, o título, o benefício principal e o botão de ação ficam acima da dobra.', 'As pessoas rolam, sim: use essa área para dar motivo para continuar, não para espremer tudo.', 'Google'),
  ('Acessibilidade', array['Accessibility']::text[], 'Interação', 'Prática de projetar produtos que possam ser usados por qualquer pessoa, incluindo quem tem deficiências visuais, motoras, auditivas ou cognitivas. Segue diretrizes como a WCAG.', 'Garantir contraste mínimo de 4.5:1 e que todo o fluxo de compra funcione só com o teclado.', 'Pense em quem usa leitor de tela, teclado ou está com o braço engessado: acessível é usável por todos.', null),
  ('Affinity Diagram', array['Diagrama de afinidade']::text[], 'Pesquisa', 'Técnica de síntese em que anotações de pesquisa são agrupadas por semelhança até que temas e padrões apareçam. Também chamada de diagrama de afinidade.', 'Depois de oito entrevistas, o time cola post-its na parede e forma grupos como "medo de errar o pagamento".', 'Afinidade = juntar o que se parece até os temas falarem por si.', null),
  ('Affordance', '{}'::text[], 'Interação', 'Propriedade de um objeto que sugere como ele pode ser usado. Um botão com relevo parece clicável; uma alça sugere puxar.', 'Uma maçaneta de alavanca convida a empurrar para baixo; um link sublinhado convida ao clique.', 'Do inglês "to afford": o que o objeto oferece fazer.', null),
  ('Agile', array['Ágil', 'Metodologias ágeis']::text[], 'Times & Métodos', 'Abordagem de desenvolvimento com entregas curtas e frequentes, colaboração constante e adaptação a mudanças, baseada no Manifesto Ágil (2001).', 'O time entrega uma melhoria a cada 2 semanas em vez de lançar tudo depois de um ano.', 'Ágil é a filosofia; Scrum e Kanban são formas de aplicá-la.', 'Silvestri'),
  ('Amostra representativa', array['Representative sample']::text[], 'Pesquisa', 'Grupo de participantes que reflete as características relevantes de todo o público estudado.', 'Se 40% dos usuários usam Android, os testes não podem ter só pessoas com iPhone.', 'Defina primeiro quais características importam para a pergunta da pesquisa.', 'Google'),
  ('API', array['Application Programming Interface']::text[], 'Times & Métodos', 'Interface que permite que dois sistemas troquem informações seguindo regras definidas.', 'O app de delivery usa a API do Google Maps para mostrar a rota do entregador.', 'Saber o que a API devolve evita desenhar telas com dados que o sistema não tem.', 'Silvestri'),
  ('Arquitetura da Informação', array['AI', 'Information Architecture', 'IA']::text[], 'Arquitetura da Informação', 'Disciplina que organiza, nomeia e estrutura o conteúdo de um produto para que as pessoas encontrem o que procuram e entendam onde estão.', 'Decidir se ''Trocas e devoluções'' fica dentro de ''Minha conta'' ou de ''Ajuda'' num e-commerce.', 'Se o usuário precisa adivinhar onde algo está, o problema é de arquitetura, não de layout.', 'Silvestri'),
  ('Atomic Design', '{}'::text[], 'Prototipação', 'Metodologia de Brad Frost que organiza interfaces em átomos, moléculas, organismos, templates e páginas, do componente mais simples ao mais complexo.', 'Um botão (átomo) + campo (átomo) formam a busca (molécula), que entra no cabeçalho (organismo).', 'Química aplicada à UI: do átomo à página.', null),
  ('Avaliação heurística', array['Heurísticas de Nielsen', 'Heuristic evaluation']::text[], 'Pesquisa', 'Inspeção em que especialistas analisam uma interface com base em princípios de usabilidade, como as 10 heurísticas de Nielsen e Molich, para encontrar problemas sem envolver usuários.', 'Revisar o checkout e notar que não há feedback depois de clicar em ''Pagar'' (heurística 1: visibilidade do status do sistema).', 'É rápida e barata, mas não substitui o teste com usuários reais: encontra problemas prováveis, não comprovados.', 'Silvestri'),
  ('Back-end', array['Back-end developer', 'Desenvolvedor back-end']::text[], 'Times & Métodos', 'Parte do software que roda no servidor (regras de negócio, banco de dados, integrações), e o profissional que a desenvolve.', 'O back-end valida o cupom de desconto e calcula o frete antes de mostrar o total.', 'Muitas limitações de UX vêm do back-end, como um campo que não pode ser editado depois.', 'Silvestri + Google'),
  ('Backlog', array['Product backlog']::text[], 'Times & Métodos', 'Lista priorizada de tudo o que o time pode fazer no produto: funcionalidades, melhorias, correções.', '''Adicionar login com Google'' está no topo do backlog; ''modo escuro'' está mais abaixo.', 'Um item bem escrito no backlog tem problema, valor e critério de pronto, não só o nome da tarefa.', 'Silvestri'),
  ('Benchmarking', array['Benchmark', 'Competitive audit', 'Auditoria competitiva']::text[], 'Estratégia', 'Análise sistemática de produtos concorrentes ou de referência para entender padrões, boas práticas e oportunidades de diferenciação.', 'Antes de redesenhar o checkout, o time compara o fluxo de cinco e-commerces líderes.', 'Bench = bancada de comparação: você mede o seu ao lado dos outros.', null),
  ('Blueprint de Serviço', '{}'::text[], 'Estratégia', 'Diagrama que mapeia a experiência do cliente junto com os processos de bastidor, pessoas e sistemas que a sustentam, camada por camada.', 'Num hotel, mapear do check-in na recepção até o sistema de reservas e a equipe de limpeza.', 'É a planta do serviço: palco (o que o cliente vê) e bastidores.', null),
  ('Breadcrumb', '{}'::text[], 'Arquitetura da Informação', 'Trilha de navegação que mostra onde a pessoa está na hierarquia do site, como Início › Categoria › Página, e permite voltar a níveis anteriores.', 'Loja › Calçados › Tênis › Corrida, no topo de uma página de produto.', 'As migalhas de pão de João e Maria: o caminho para voltar.', null),
  ('Bug', array['Defeito']::text[], 'Times & Métodos', 'Erro no software que faz algo funcionar de forma diferente do esperado.', 'O botão ''Salvar'' funciona no computador, mas não responde no iPhone.', 'Ao reportar um bug, informe passos, dispositivo, o resultado esperado e o que aconteceu.', 'Silvestri'),
  ('Call to Action', array['CTA', 'Call-to-action']::text[], 'Interação', 'Elemento, geralmente um botão ou link, que convida a pessoa a realizar a ação principal da tela, como assinar, comprar ou continuar.', 'O botão "Começar teste grátis" em destaque na página inicial de um SaaS.', 'CTA = o convite principal da tela. Se houver três, nenhum é principal.', null),
  ('Card Sorting', '{}'::text[], 'Pesquisa', 'Método em que participantes organizam cartões com conteúdos em grupos que façam sentido para eles. Revela modelos mentais e orienta a arquitetura da informação.', 'Participantes agrupam 40 cartões de serviços bancários; o grupo "meu dinheiro" vira um item de menu.', 'Aberto: as pessoas criam as categorias. Fechado: elas usam as suas.', null),
  ('Cards', array['Cartões']::text[], 'Interação', 'Componentes retangulares que agrupam conteúdo e ações sobre um único assunto.', 'Cada restaurante num app de delivery aparece como um card com foto, nome, nota e tempo de entrega.', 'Defina qual é a área clicável do card: o card inteiro ou só um botão dentro dele.', 'Google'),
  ('Carga Cognitiva', '{}'::text[], 'Interação', 'Quantidade de esforço mental necessária para usar uma interface. Quanto menos a pessoa precisa lembrar, decidir ou interpretar, menor a carga.', 'Um formulário que pede o CEP e já preenche o endereço reduz o que a pessoa precisa lembrar.', 'Cada decisão e cada coisa para memorizar pesa na mochila mental.', null),
  ('Carrossel', array['Carousel', 'Carousels']::text[], 'Interação', 'Componente que mostra itens em sequência horizontal, navegados por toque, setas ou rotação automática.', 'Banners rotativos com promoções no topo de uma loja online.', 'Os primeiros itens recebem quase toda a atenção; não esconda conteúdo importante nos últimos.', 'Google'),
  ('Chatbot', array['Bot de conversa']::text[], 'Interação', 'Sistema que conversa com o usuário por texto ou voz, seguindo regras ou usando IA, para responder dúvidas ou executar tarefas.', 'O assistente do banco que mostra o saldo quando você digita ''quanto tenho na conta?''.', 'Sempre ofereça uma saída para um atendente humano: ficar preso num bot é uma das maiores frustrações.', 'Silvestri'),
  ('Concorrentes diretos e indiretos', array['Direct competitors', 'Indirect competitors']::text[], 'Estratégia', 'Concorrentes diretos oferecem um produto parecido ao mesmo público; indiretos resolvem o mesmo problema de outra forma ou atendem outro público.', 'Para um app de bicicletários: outro app de mapa de bike é direto; o estacionamento de shopping é indireto.', 'Os indiretos costumam revelar como as pessoas resolvem o problema hoje.', 'Google'),
  ('Consistência', array['Consistency']::text[], 'Interação', 'Uso dos mesmos padrões visuais, de texto e de comportamento em todo o produto, para que ele pareça familiar.', 'O botão principal tem sempre a mesma cor e fica sempre no mesmo lugar em todos os formulários.', 'Um design system é a forma mais eficiente de manter consistência.', 'Google'),
  ('Content Inventory', '{}'::text[], 'Arquitetura da Informação', 'Levantamento completo de todo o conteúdo existente de um produto, com localização, tipo e responsável. Base para auditorias e reestruturações.', 'Uma planilha com as 300 páginas do site, a URL, o dono e a data da última atualização.', 'Inventário vem antes da auditoria: primeiro conte, depois avalie.', null),
  ('Continuidade', array['Continuity', 'Lei da continuidade']::text[], 'Design Visual', 'Princípio da Gestalt: o olho tende a seguir linhas e caminhos contínuos.', 'Um carrossel com o próximo card cortado na borda convida a rolar para o lado.', 'Alinhe elementos em linhas claras para guiar a leitura.', 'Google'),
  ('Copywriting', array['Copy']::text[], 'Estratégia', 'Escrita persuasiva voltada a convencer e gerar ação, vinda da publicidade. Em produto, aparece em landing pages, anúncios e campanhas.', 'O título ''Frete grátis na sua primeira compra'' na página inicial de uma loja.', 'Não confunda com UX Writing: copy vende, UX Writing orienta o uso da interface.', 'Silvestri'),
  ('Crítica de design', array['Design critique', 'Design critique session', 'Design review']::text[], 'Times & Métodos', 'Sessão em que o time analisa um design com base nos objetivos do projeto, para melhorá-lo.', 'A designer apresenta 3 opções de onboarding e o time comenta cada uma com base na meta de reduzir abandono.', 'Critique o trabalho em relação ao objetivo (''isso ajuda a reduzir abandono?''), não o gosto pessoal.', 'Google'),
  ('Customer Experience', array['CX', 'Experiência do cliente']::text[], 'Estratégia', 'A experiência completa do cliente com uma marca, somando todos os pontos de contato: site, loja física, atendimento, entrega e pós-venda.', 'O app de delivery é ótimo, mas o pedido chega frio e o suporte não responde: a UX vai bem, a CX vai mal.', 'UX é uma parte da CX. Um produto digital bom não salva uma experiência ruim no resto da jornada.', 'Silvestri'),
  ('Customer Journey Map', array['Jornada do usuário', 'User journey']::text[], 'Estratégia', 'Representação visual das etapas que uma pessoa percorre ao interagir com um produto ou serviço, com ações, pensamentos, emoções e pontos de dor em cada fase.', 'Mapear a jornada de quem aluga um apartamento: busca, visita, contrato, mudança e primeiro mês.', 'Linha do tempo + emoções: onde a curva cai é a oportunidade.', null),
  ('Daily', array['Daily meeting', 'Daily Scrum', 'Stand-up']::text[], 'Times & Métodos', 'Reunião diária de até 15 minutos para o time alinhar o andamento e identificar bloqueios.', '''Ontem terminei o protótipo, hoje testo com 3 usuários, estou bloqueada esperando acesso ao Figma do cliente.''', 'Daily não é lugar para resolver problemas: anote e resolva depois com quem precisa.', 'Silvestri'),
  ('Declaração de hipótese', array['Hypothesis statement']::text[], 'Estratégia', 'Suposição testável sobre qual solução resolve o problema e qual resultado se espera.', '''Se mostrarmos bicicletários num mapa, ciclistas vão encontrar onde parar em menos de 1 minuto.''', 'Formato útil: ''Se fizermos X, então Y vai acontecer, e saberemos pela métrica Z.''', 'Google'),
  ('Declaração do problema', array['Problem statement']::text[], 'Estratégia', 'Frase clara que descreve quem é o usuário, qual é a necessidade dele e por que ela importa.', '''Ciclistas urbanos precisam de um lugar seguro para guardar a bike porque têm medo de furto ao parar na rua.''', 'Uma boa declaração não traz a solução dentro dela.', 'Google'),
  ('Degradação graciosa', array['Graceful degradation', 'Top-down designing']::text[], 'Prototipação', 'Estratégia de projetar primeiro para a tela maior e completa e depois simplificar para telas menores.', 'Começar pelo painel completo do desktop e decidir o que sai na versão de celular.', 'É o oposto do mobile first. O risco é o celular virar uma versão espremida.', 'Google'),
  ('Design Centrado no Usuário', array['DCU', 'UCD', 'User-centered design']::text[], 'Estratégia', 'Abordagem que envolve os usuários e suas necessidades em todas as etapas do projeto, iterando com base em pesquisa e testes (descrita na norma ISO 9241-210).', 'Testar um protótipo com 5 pessoas antes de desenvolver, em vez de lançar e esperar reclamações.', 'Centrado no usuário não é fazer tudo o que o usuário pede: é entender o problema dele a fundo.', 'Silvestri'),
  ('Design de Interação', array['IxD', 'Interaction design', 'Interaction designer']::text[], 'Interação', 'Área que define como pessoa e produto ''conversam'': as ações possíveis, as respostas do sistema e o comportamento de cada elemento.', 'Definir o que acontece quando você arrasta um e-mail para o lado: arquiva, mostra ''desfazer'' e anima a saída da lista.', 'Pense em ''o que o usuário faz'' e ''o que o sistema responde'', sempre em par.', 'Silvestri + Google'),
  ('Design inclusivo', array['Inclusive design']::text[], 'Estratégia', 'Abordagem que considera a diversidade de pessoas (habilidades, idade, idioma, contexto) desde o início do projeto.', 'Projetar um app que funcione bem com uma mão só, pensando em quem segura um bebê ou o guidão da bike.', 'Pense em limitações permanentes, temporárias e situacionais: um braço engessado e um ônibus lotado também contam.', 'Google'),
  ('Design responsivo', array['Responsive web design', 'Responsive design']::text[], 'Prototipação', 'Design que se adapta a diferentes tamanhos de tela, reorganizando o layout de forma fluida.', 'Três colunas de produtos no desktop viram uma coluna só no celular.', 'Teste nos tamanhos reais (375px, 768px, 1280px), não só esticando a janela do navegador.', 'Google'),
  ('Design Sprint', array['Sprint brief']::text[], 'Estratégia', 'Processo de cinco dias, criado no Google Ventures, para sair de um problema até um protótipo testado com usuários reais.', 'Segunda: mapear o problema. Sexta: testar o protótipo com cinco clientes.', 'Cinco dias: entender, esboçar, decidir, prototipar, testar.', null),
  ('Design System', '{}'::text[], 'Prototipação', 'Conjunto de componentes reutilizáveis, padrões, tokens e diretrizes que mantém a consistência visual e de comportamento de um produto.', 'O Material Design, do Google, com componentes, tokens de cor e regras de uso documentadas.', 'Mais que uma biblioteca de componentes: inclui o porquê de cada decisão.', null),
  ('Design thinking', array['Empatizar, definir, idear, prototipar, testar']::text[], 'Estratégia', 'Abordagem de resolução de problemas centrada nas pessoas, frequentemente descrita em 5 etapas: empatizar, definir, idear, prototipar e testar.', 'Entrevistar ciclistas (empatizar), definir ''não acham onde guardar a bike'' (definir), gerar ideias, prototipar um mapa e testá-lo.', 'As etapas não são lineares: é normal voltar para a pesquisa depois de um teste.', 'Google'),
  ('Design universal', array['Universal design']::text[], 'Estratégia', 'Princípio de criar produtos e ambientes que possam ser usados pelo maior número possível de pessoas, sem necessidade de adaptação.', 'Portas automáticas servem a cadeirantes, pessoas com sacolas e pais com carrinho de bebê.', 'Inclusivo e universal se complementam: um busca a diversidade, o outro uma solução única para todos.', 'Google'),
  ('Desk Research', array['Pesquisa secundária', 'Secondary research']::text[], 'Pesquisa', 'Pesquisa secundária feita a partir de fontes já existentes, como relatórios, artigos, dados públicos e estudos anteriores, sem contato direto com usuários.', 'Ler relatórios de mercado e estudos acadêmicos antes de marcar a primeira entrevista.', 'Feita da mesa (desk): ninguém novo é entrevistado.', null),
  ('Double Diamond', '{}'::text[], 'Estratégia', 'Modelo de processo do Design Council com quatro fases: descobrir, definir, desenvolver e entregar. Alterna momentos de divergência e convergência.', 'Primeiro diamante: descobrir que o problema real é a confiança. Segundo: testar soluções para ela.', 'Dois diamantes = abrir e fechar duas vezes: problema certo, depois solução certa.', null),
  ('Edge case', array['Caso extremo', 'Caso de borda']::text[], 'Prototipação', 'Situação fora do uso comum, muitas vezes fora do controle do usuário, que o design precisa prever.', 'O que aparece quando a busca não encontra nada, quando a internet cai ou quando o nome tem 60 letras?', 'Liste os edge cases antes de entregar ao dev; senão, quem decide é o código.', 'Google'),
  ('Efeito curb cut', array['Curb cut effect', 'Efeito rampa']::text[], 'Estratégia', 'Fenômeno em que soluções criadas para pessoas com deficiência acabam beneficiando todo mundo.', 'Rampas na calçada foram feitas para cadeirantes e hoje ajudam quem anda de bike, carrega mala ou empurra carrinho.', 'Legendas são outro exemplo: quem mais usa são pessoas vendo vídeo sem som no transporte.', 'Google'),
  ('Efeito de posição serial', array['Serial position effect']::text[], 'Interação', 'Tendência de lembrar melhor os primeiros e os últimos itens de uma lista, e pior os do meio.', 'Barras de navegação colocam as opções mais importantes nas pontas, como ''Início'' e ''Perfil''.', 'Nunca deixe a ação mais importante no meio de uma lista longa.', 'Google'),
  ('Empty State', '{}'::text[], 'Interação', 'Tela ou área exibida quando ainda não há conteúdo, como uma lista vazia. Bem projetado, explica o motivo e indica o próximo passo.', '"Você ainda não tem projetos. Crie o primeiro" com um botão, no lugar de uma lista em branco.', 'Vazio não é erro: é a chance de ensinar o próximo passo.', null),
  ('Entrevista com usuários', array['Interviews', 'User interview', 'Entrevista']::text[], 'Pesquisa', 'Conversa estruturada com uma pessoa para entender experiências, necessidades e motivações.', '''Me conta sobre a última vez que você precisou guardar a bike na rua.''', 'Pergunte sobre o passado concreto, não sobre o futuro: ''você usaria?'' gera respostas pouco confiáveis.', 'Google'),
  ('Espaço negativo', array['Negative space', 'White space', 'Espaço em branco', 'Respiro']::text[], 'Design Visual', 'Área vazia entre e ao redor dos elementos, que organiza o conteúdo e dá respiro à leitura.', 'Aumentar a margem entre seções de um artigo deixa o texto mais fácil de ler.', 'Espaço vazio não é desperdício: é um recurso de organização.', 'Google'),
  ('Estudo de caso', array['Case study', 'Case studies', 'Case']::text[], 'Times & Métodos', 'Apresentação de um projeto de design mostrando objetivo, papel da pessoa, processo, decisões e resultados.', 'Um case de portfólio que mostra da pesquisa com ciclistas ao protótipo final do mapa de bicicletários.', 'Recrutadores querem ver como você pensa: mostre decisões e trade-offs, não só telas bonitas.', 'Google'),
  ('Experience Map', array['Mapa da experiência', 'Mapa de experiência']::text[], 'Pesquisa', 'Mapa amplo de uma experiência humana completa, independente de um produto específico, com ações, emoções e necessidades em cada etapa.', 'Mapear ''mudar de apartamento'' do início ao fim, antes de decidir onde um app de mudanças pode ajudar.', 'A jornada olha para o seu produto; o mapa de experiência olha para a vida da pessoa.', 'Silvestri'),
  ('Experiência omnichannel', array['Omnichannel', 'Omnicanal']::text[], 'Estratégia', 'Experiência integrada entre canais (app, site, loja física, atendimento), em que o cliente continua de onde parou ao trocar de canal.', 'Comprar pelo app, retirar na loja e trocar o produto pelo site sem repetir nenhuma informação.', 'Multicanal é estar em vários canais; omnichannel é eles conversarem entre si.', 'Silvestri'),
  ('Falácia do custo afundado', array['Sunk cost fallacy', 'Custo irrecuperável']::text[], 'Estratégia', 'Tendência a continuar investindo em algo só por causa do que já foi gasto, mesmo quando as evidências dizem para parar.', 'Manter uma funcionalidade que ninguém usa porque o time levou 3 meses para construí-la.', 'Decida pelo valor futuro, não pelo esforço passado.', 'Google'),
  ('Feedback', array['Feedback do sistema']::text[], 'Interação', 'Resposta do sistema a uma ação da pessoa, visual, sonora ou tátil, que confirma o que aconteceu, como um botão que muda de estado ao ser pressionado.', 'O botão "Enviar" vira "Enviando…" e depois mostra "Mensagem enviada".', 'Toda ação merece uma resposta visível do sistema.', null),
  ('Fidelidade', array['Fidelity', 'Low fidelity', 'Lo-fi', 'High fidelity', 'Hi-fi', 'Baixa fidelidade', 'Alta fidelidade']::text[], 'Prototipação', 'Quanto um protótipo se parece com o produto final. Baixa fidelidade é simples e rápida; alta fidelidade é próxima do produto real.', 'Esboço em papel (lo-fi) para testar o fluxo; protótipo no Figma com cores e interações (hi-fi) para testar detalhes.', 'Comece em baixa fidelidade: as pessoas criticam mais livremente algo que parece inacabado.', 'Google'),
  ('Fluxo de Usuário', array['User flow', 'Userflow', 'Fluxo do usuário']::text[], 'Arquitetura da Informação', 'Diagrama que mostra o caminho passo a passo que uma pessoa percorre para completar uma tarefa, incluindo telas, decisões e desvios.', 'Do e-mail de recuperação até a nova senha salva, com o desvio de link expirado.', 'Fluxo é sobre o caminho e as decisões, não sobre o visual das telas.', null),
  ('Front-end', array['Front-end developer', 'Desenvolvedor front-end']::text[], 'Times & Métodos', 'Parte do software que a pessoa vê e com a qual interage, e o profissional que a desenvolve com HTML, CSS e JavaScript.', 'O dev front-end transforma as telas do Figma em páginas funcionais no navegador.', 'Converse com o front-end cedo: ele sabe o que é simples ou caro de construir.', 'Silvestri + Google'),
  ('Grid', array['Layout grid', 'Basic grid', 'Grade']::text[], 'Design Visual', 'Estrutura invisível de colunas, margens e espaçamentos que alinha os elementos de uma tela.', 'Grid de 12 colunas no desktop e de 4 colunas no celular.', 'Defina o grid antes de desenhar: ele torna o layout consistente entre telas.', 'Google'),
  ('Guerrilla Testing', '{}'::text[], 'Pesquisa', 'Teste de usabilidade rápido e informal, feito com pessoas abordadas em locais públicos, para obter sinais iniciais com baixo custo.', 'Pedir a clientes de um café que tentem achar o horário de funcionamento num protótipo.', 'Guerrilha = rápido, barato e onde as pessoas estão.', null),
  ('Hackathon', '{}'::text[], 'Times & Métodos', 'Evento de curta duração, geralmente de 1 a 3 dias, em que equipes multidisciplinares criam soluções para um desafio.', 'Em 48 horas, uma equipe de design, dev e dados entrega o protótipo de um app para ONGs.', 'Em hackathon, um problema bem definido vale mais do que muitas funcionalidades.', 'Silvestri'),
  ('Happy path', array['Caminho feliz']::text[], 'Prototipação', 'O caminho ideal de uma tarefa, em que tudo dá certo sem erros nem desvios.', 'Abrir o app, escolher o produto, pagar com o cartão salvo e receber a confirmação.', 'Desenhe o caminho feliz primeiro, mas não pare nele: os erros também precisam de tela.', 'Google'),
  ('Heurísticas de Nielsen', '{}'::text[], 'Pesquisa', 'Dez princípios gerais de usabilidade definidos por Jakob Nielsen, como visibilidade do status do sistema e prevenção de erros. Usados em avaliações heurísticas.', 'Avaliar um app e notar que ele não mostra progresso durante o upload (visibilidade do status).', 'São dez. Comece pelas mais lembradas: status do sistema, controle do usuário, prevenção de erros.', null),
  ('Hierarquia tipográfica', array['Typographic hierarchy']::text[], 'Design Visual', 'Uso de tamanhos, pesos e estilos de texto diferentes para mostrar a importância de cada informação.', 'Título 24px em negrito, subtítulo 18px e corpo de texto 16px.', 'Defina uma escala de tamanhos e use só ela: evita 11 tamanhos de fonte diferentes no mesmo produto.', 'Google'),
  ('Hierarquia visual', array['Hierarchy', 'Visual hierarchy']::text[], 'Design Visual', 'Organização dos elementos por importância, usando tamanho, cor, peso e posição para indicar o que ler primeiro.', 'Na tela de pagamento, o valor total é o maior texto e o botão ''Pagar'' é o mais destacado.', 'Faça o teste do olhar desfocado: o que ainda aparece deve ser o mais importante.', 'Google'),
  ('História de usuário', array['User story']::text[], 'Times & Métodos', 'Descrição curta de uma necessidade do ponto de vista do usuário, usada para planejar o trabalho.', '''Como ciclista, quero ver bicicletários próximos para parar com segurança.''', 'Formato: ''Como [tipo de usuário], quero [ação] para [benefício].''', 'Google'),
  ('Iconografia', array['Iconography', 'Ícones']::text[], 'Design Visual', 'Conjunto de ícones de um produto e as regras de estilo que os mantêm consistentes.', 'Todos os ícones com o mesmo traço de 1,5px e cantos arredondados.', 'Ícones pouco conhecidos precisam de rótulo: um ícone sozinho é ambíguo.', 'Google'),
  ('Ideação', array['Ideate', 'Ideation', 'Idear']::text[], 'Prototipação', 'Etapa de gerar muitas ideias de solução antes de escolher quais seguir.', 'Crazy 8s: dobrar uma folha em 8 e desenhar 8 ideias em 8 minutos.', 'Quantidade primeiro, julgamento depois. Criticar durante a geração mata boas ideias cedo.', 'Google'),
  ('Identidade de marca', array['Brand identity', 'Identidade visual']::text[], 'Design Visual', 'Conjunto de elementos visuais e de linguagem que tornam uma marca reconhecível: logo, cores, tipografia e tom de voz.', 'Um app de banco com tom de voz informal e cor roxa forte em todas as telas.', 'A identidade da marca deve aparecer no produto sem atrapalhar a usabilidade.', 'Google'),
  ('Insight', '{}'::text[], 'Pesquisa', 'Descoberta sobre as pessoas que revela uma necessidade ou motivação de forma nova e acionável.', 'Dado: ''usuários abandonam o carrinho''. Insight: ''eles usam o carrinho como lista de desejos, não como intenção de compra''.', 'Um insight explica um porquê. Se for só um número, ainda é um dado.', 'Google'),
  ('Interação', array['Interaction']::text[], 'Interação', 'Qualquer troca entre a pessoa e o produto: um toque, um clique, um comando de voz e a resposta que o sistema dá.', 'Tocar no coração de um post e ver o ícone ficar vermelho e o contador subir.', 'Não confunda com iteração: interação é uso, iteração é repetir o ciclo para melhorar.', 'Silvestri'),
  ('Interação Humano-Computador', array['IHC', 'HCI', 'Human-Computer Interaction']::text[], 'Pesquisa', 'Campo acadêmico que estuda como as pessoas usam sistemas computacionais e como projetá-los melhor. É uma das bases científicas da UX.', 'Estudos de IHC deram origem a leis como a de Fitts, usada até hoje para dimensionar botões.', 'Não é um termo aposentado: é um campo de pesquisa ativo, com congressos e grupos em universidades brasileiras.', 'Silvestri'),
  ('Iteração', array['Iterate', 'Iterar']::text[], 'Prototipação', 'Ciclo de criar, testar, aprender e ajustar, repetido até a solução funcionar bem.', 'Versão 1 do cadastro testada, 3 pessoas travam no CPF, versão 2 ganha máscara automática e é testada de novo.', 'Planeje tempo para iterar no cronograma: a primeira versão quase nunca é a final.', 'Silvestri + Google'),
  ('Jobs to Be Done', '{}'::text[], 'Estratégia', 'Abordagem que entende produtos como algo que as pessoas contratam para realizar um trabalho ou progresso na vida, em vez de focar em perfis demográficos.', 'As pessoas não compram uma furadeira; elas contratam um furo na parede para pendurar um quadro.', 'Pergunte: que progresso a pessoa quer fazer quando "contrata" o produto?', null),
  ('KPI', array['Key Performance Indicator', 'Indicador-chave de desempenho', 'KPIs']::text[], 'Estratégia', 'Indicador escolhido para acompanhar se um objetivo está sendo alcançado.', 'Para um app de agendamento, um KPI pode ser ''consultas marcadas por semana''.', 'Poucos KPIs bem escolhidos valem mais do que um painel cheio de números.', 'Google'),
  ('Lean Startup', array['Lean', 'Startup enxuta']::text[], 'Estratégia', 'Método de Eric Ries para criar produtos com pouco desperdício, usando o ciclo construir, medir e aprender.', 'Lançar uma página com ''Em breve, cadastre-se'' para medir interesse antes de construir o produto.', 'A pergunta central é: qual é o menor experimento que testa esta hipótese?', 'Silvestri'),
  ('Lean UX', '{}'::text[], 'Estratégia', 'Abordagem que reduz entregáveis formais e foca em hipóteses testadas rapidamente, inspirada em Lean Startup e métodos ágeis.', 'Em vez de 40 telas documentadas, o time testa uma hipótese com um protótipo de 3 telas em uma semana.', 'Lean não é ''sem pesquisa'': é pesquisa rápida e contínua, ligada a hipóteses claras.', 'Silvestri'),
  ('Lei de Fitts', '{}'::text[], 'Interação', 'Princípio que diz que o tempo para alcançar um alvo depende da distância até ele e do seu tamanho. Alvos grandes e próximos são mais rápidos de acertar.', 'Botões principais grandes e perto do polegar no celular; menus nas bordas da tela no desktop.', 'Grande e perto = rápido. Pequeno e longe = lento.', null),
  ('Lei de Hick', '{}'::text[], 'Interação', 'Princípio que diz que o tempo de decisão aumenta com o número e a complexidade das opções. Menos escolhas por vez tornam a decisão mais rápida.', 'Um menu de restaurante com 80 pratos atrasa a escolha; dividir em seções acelera.', 'Mais opções, mais tempo para decidir.', null),
  ('Leitor de tela', array['Screen reader']::text[], 'Interação', 'Software que lê em voz alta o conteúdo e os elementos da tela, usado principalmente por pessoas cegas ou com baixa visão.', 'VoiceOver (iPhone), TalkBack (Android) e NVDA (Windows).', 'Ative o leitor do seu celular e tente usar seu app de olhos fechados: os problemas aparecem rápido.', 'Google'),
  ('Letramento digital', array['Digital literacy']::text[], 'Pesquisa', 'Nível de habilidade de uma pessoa para usar tecnologias e informações digitais.', 'Uma pessoa idosa que só usa WhatsApp pode não reconhecer o ícone de menu hambúrguer.', 'Inclua pessoas com diferentes níveis de letramento digital nos testes, não só colegas de tecnologia.', 'Google'),
  ('Lo-fi', '{}'::text[], 'Prototipação', 'Protótipo de baixa fidelidade, como esboços em papel ou wireframes simples, usado para testar ideias cedo e barato, sem detalhes visuais.', 'Esboços em papel de três layouts de tela inicial, testados antes de abrir o Figma.', 'Low fidelity: feio de propósito, para as pessoas criticarem a ideia e não a cor.', null),
  ('Lorem ipsum', array['Texto de preenchimento', 'Placeholder text']::text[], 'Prototipação', 'Texto em latim embaralhado usado para preencher layouts quando o conteúdo real ainda não existe.', 'Um card de notícia com ''Lorem ipsum dolor sit amet'' no lugar da manchete.', 'Use com moderação: textos reais costumam ser mais longos e quebram o layout.', 'Google'),
  ('Mapa de Empatia', array['Empathy map', 'Aggregated empathy map', 'Mapa da empatia']::text[], 'Pesquisa', 'Ferramenta que organiza o que uma pessoa diz, pensa, faz e sente, para criar um entendimento compartilhado sobre suas necessidades.', 'Um quadro com quatro áreas preenchido pelo time após entrevistar motoristas de aplicativo.', 'Diz, pensa, faz, sente.', null),
  ('Menu hambúrguer', array['Hamburger menu', 'Hamburger menus']::text[], 'Interação', 'Ícone de três linhas que abre um menu de navegação escondido.', 'No celular, as seções do site ficam dentro do ícone ☰ no canto da tela.', 'Esconder a navegação reduz o uso. Opções principais podem ficar visíveis numa barra inferior.', 'Google'),
  ('Microinteração', '{}'::text[], 'Interação', 'Pequeno momento de interação com um único propósito, como curtir uma publicação ou ligar um interruptor, composto de gatilho, regras, feedback e ciclos.', 'O coração que pulsa ao curtir uma foto, ou o interruptor que desliza ao ativar o modo escuro.', 'Gatilho, regras, feedback, ciclos e modos.', null),
  ('Mobile first', array['Mobile-first philosophy', 'Aprimoramento progressivo', 'Progressive enhancement']::text[], 'Prototipação', 'Estratégia de projetar primeiro para a tela menor e acrescentar recursos à medida que a tela cresce.', 'Definir o que é essencial no celular e depois aproveitar o espaço extra no desktop.', 'Obriga a priorizar: se não cabe no celular, talvez não seja essencial.', 'Google'),
  ('Mockup', '{}'::text[], 'Prototipação', 'Representação estática de alta fidelidade visual de uma tela, com cores, tipografia e imagens finais, mas sem interação.', 'A tela final do app em alta fidelidade, mostrada ao cliente para aprovação visual.', 'Mockup mostra como fica; protótipo mostra como funciona.', null),
  ('Modelo Mental', array['Mental model', 'Mental models']::text[], 'Interação', 'Crença que a pessoa tem sobre como um sistema funciona, formada por experiências anteriores. Interfaces que respeitam esse modelo parecem intuitivas.', 'Muita gente espera que o ícone de lixeira apague; se ele arquivar, quebra o modelo mental.', 'É o que a pessoa acha que vai acontecer, não o que de fato acontece.', null),
  ('MVP', array['Produto Mínimo Viável', 'Minimum Viable Product']::text[], 'Estratégia', 'Minimum Viable Product: a versão mais simples de um produto capaz de entregar valor e gerar aprendizado validado com usuários reais.', 'Antes de criar o app, testar a demanda com uma página de inscrição e entregas feitas à mão.', 'Mínimo para aprender, não mínimo para lançar.', null),
  ('Net Promoter Score', array['NPS']::text[], 'Estratégia', 'Métrica de lealdade baseada em uma pergunta de 0 a 10 (''quanto você recomendaria?''). NPS = % de promotores (9–10) menos % de detratores (0–6).', '60% de promotores e 15% de detratores resultam em NPS de 45.', 'O número sozinho diz pouco: a pergunta aberta ''por quê?'' é o que gera aprendizado.', 'Silvestri'),
  ('North Star Metric', '{}'::text[], 'Estratégia', 'Métrica única que melhor representa o valor que o produto entrega aos clientes e orienta as decisões de todo o time.', 'No Spotify, o tempo de escuta; no Airbnb, as noites reservadas.', 'Uma estrela que todos os times conseguem ver e seguir.', null),
  ('Onboarding', '{}'::text[], 'Interação', 'Experiência inicial que ajuda uma pessoa nova a entender o produto e chegar rapidamente ao primeiro momento de valor.', 'No primeiro acesso, o app de finanças pede só para conectar uma conta e já mostra o saldo.', 'O objetivo é o primeiro momento de valor, não um tour por todas as telas.', null),
  ('Ordem de foco', array['Traversal order', 'Focus order', 'Ordem de navegação']::text[], 'Interação', 'Sequência em que os elementos recebem foco quando a pessoa navega pelo teclado ou por tecnologia assistiva.', 'Num formulário, a tecla Tab deve ir de ''Nome'' para ''E-mail'' e só depois para ''Enviar''.', 'Teste seu protótipo só com Tab, Enter e Esc: se você se perder, quem usa leitor de tela também vai.', 'Google'),
  ('Padrão F', array['F-shape layout', 'F-pattern']::text[], 'Design Visual', 'Padrão de leitura em que o olhar percorre a parte de cima, depois uma faixa um pouco abaixo e desce pela lateral esquerda, como um F.', 'Resultados de busca e páginas com muito texto costumam ser lidos assim.', 'Coloque as palavras mais importantes no começo de títulos e linhas.', 'Google'),
  ('Padrão Z', array['Z-shape layout', 'Z-pattern']::text[], 'Design Visual', 'Padrão de leitura em telas com pouco texto, em que o olhar vai da esquerda para a direita no topo, cruza na diagonal e repete embaixo, como um Z.', 'Landing page com logo no topo à esquerda, menu à direita, imagem no meio e botão no canto inferior direito.', 'Funciona em páginas simples; para muito texto, pense no padrão F.', 'Google'),
  ('Padrões enganosos', array['Deceptive patterns', 'Dark patterns']::text[], 'Interação', 'Práticas de design que induzem o usuário a fazer algo que não faria se entendesse claramente.', 'Assinatura fácil de fazer em 1 clique, mas cancelamento só por telefone em horário comercial.', 'Além de antiéticos, muitos violam leis de defesa do consumidor e de proteção de dados.', 'Google'),
  ('Persona', array['Avatar']::text[], 'Pesquisa', 'Personagem fictício baseado em dados de pesquisa que representa um grupo de usuários, com objetivos, comportamentos e frustrações.', '"Carla, 34, enfermeira, faz compras no celular nos intervalos do plantão."', 'Sem dados de pesquisa por trás, é só um estereótipo com foto.', null),
  ('Peso visual', array['Visual weight', 'Equilíbrio visual', 'Visual balance']::text[], 'Design Visual', 'Quanto um elemento atrai o olhar, influenciado por tamanho, cor, contraste e densidade.', 'Um botão vermelho pequeno pode chamar mais atenção que um bloco cinza grande.', 'Distribua o peso visual para equilibrar a tela e não competir com a ação principal.', 'Google'),
  ('Pesquisa com usuários', array['User research', 'UX research', 'Design research']::text[], 'Pesquisa', 'Conjunto de métodos para entender necessidades, comportamentos e motivações das pessoas que usam (ou vão usar) um produto.', 'Entrevistas, testes de usabilidade e questionários antes de redesenhar um app de agendamento.', 'Comece pela pergunta de pesquisa, não pelo método: o método vem depois.', 'Silvestri + Google'),
  ('Pesquisa etnográfica', array['Etnografia']::text[], 'Pesquisa', 'Pesquisa em que o pesquisador observa as pessoas no próprio contexto delas, para entender comportamentos reais e não apenas o que elas dizem.', 'Acompanhar entregadores durante um turno para entender como usam o app com uma mão só.', 'O que as pessoas fazem costuma ser diferente do que elas dizem que fazem.', 'Silvestri'),
  ('Pesquisa primária', array['Primary research']::text[], 'Pesquisa', 'Pesquisa feita diretamente pelo time, com dados coletados para aquele projeto.', 'Entrevistas e testes de usabilidade conduzidos por você.', 'O contrário é a pesquisa secundária (desk research), que usa dados que já existem.', 'Google'),
  ('Pesquisa qualitativa', array['Qualitative research']::text[], 'Pesquisa', 'Pesquisa que busca entender o porquê e o como, com dados descritivos de poucos participantes.', 'Entrevistar 6 pessoas para entender por que elas desistem do cadastro.', 'Com 5 a 8 participantes por perfil já aparecem os padrões principais.', 'Google'),
  ('Pesquisa quantitativa', array['Quantitative research']::text[], 'Pesquisa', 'Pesquisa que mede o quanto e o quantos, com dados numéricos de muitos participantes.', 'Analisar que 42% dos usuários abandonam o cadastro na etapa do CPF.', 'O quantitativo mostra onde está o problema; o qualitativo explica por quê.', 'Google'),
  ('Planning', array['Sprint planning', 'Planejamento da sprint']::text[], 'Times & Métodos', 'Reunião no início da sprint em que o time escolhe os itens do backlog que vai entregar e planeja como fazê-los.', 'O time define que, nesta sprint, entregará a nova tela de perfil e a correção do login.', 'Leve os itens de design já discutidos: chegar com dúvidas abertas atrasa a sprint inteira.', 'Silvestri'),
  ('Pontos de dor', array['Pain points', 'Dores']::text[], 'Pesquisa', 'Problemas ou frustrações que o usuário enfrenta na experiência atual.', 'Ter que digitar o endereço completo em cada pedido é um ponto de dor de um app de delivery.', 'Classifique as dores por tipo (financeira, de processo, de suporte, de produtividade) para priorizar melhor.', 'Google'),
  ('Princípios da Gestalt', array['Gestalt', 'Gestalt principles']::text[], 'Design Visual', 'Princípios da psicologia que descrevem como o cérebro agrupa e organiza o que vemos, como proximidade, similaridade, região comum e continuidade.', 'Agrupar campos de endereço juntos e separados dos dados de pagamento.', 'Quase todo problema de ''tela confusa'' se resolve com espaçamento e agrupamento bem feitos.', 'Google'),
  ('Product Designer', array['Designer de produto']::text[], 'Times & Métodos', 'Profissional que atua no ciclo inteiro de um produto digital, da pesquisa à interface, conectando necessidades do usuário a objetivos de negócio.', 'Participar da definição de métricas, conduzir testes e entregar as telas finais de uma funcionalidade.', 'O nome do cargo varia muito entre empresas: leia as responsabilidades da vaga, não só o título.', 'Silvestri + Google'),
  ('Product Owner', array['PO']::text[], 'Times & Métodos', 'No Scrum, a pessoa responsável por maximizar o valor do produto, priorizando e cuidando do backlog.', 'A PO decide que o login com Google entra antes do modo escuro porque reduz abandono no cadastro.', 'PO e designer trabalham juntos: leve evidências de pesquisa para influenciar a priorização.', 'Silvestri'),
  ('Produto', array['Product']::text[], 'Estratégia', 'Em UX, qualquer coisa criada para resolver um problema de alguém, inclusive digital: app, site, sistema ou serviço.', 'Um curso online, um app de banco e uma plataforma de agendamento são todos produtos.', 'Produto não precisa ser físico, mas sempre precisa resolver um problema real.', 'Silvestri + Google'),
  ('Progressive Disclosure', '{}'::text[], 'Interação', 'Técnica que mostra primeiro só o essencial e revela opções avançadas sob demanda, reduzindo a complexidade percebida.', 'Um campo "Opções avançadas" que só abre os filtros extras quando a pessoa clica.', 'Primeiro o essencial; o resto sob demanda.', null),
  ('Proposta de Valor', array['Value proposition']::text[], 'Estratégia', 'Declaração clara do benefício que o produto entrega, para quem e por que é melhor que as alternativas.', '"Envie dinheiro para o exterior em minutos, com a taxa real do câmbio."', 'Para quem, qual benefício e por que você em vez da alternativa.', null),
  ('Proto persona', array['Protopersona']::text[], 'Pesquisa', 'Persona provisória criada a partir de suposições do time, antes de existir pesquisa com usuários.', 'No primeiro dia do projeto, o time descreve ''Ana, 30 anos, pede comida 3 vezes por semana'' para alinhar hipóteses.', 'Use para alinhar o time e defina quando ela será validada com pesquisa. Nunca a apresente como dado real.', 'Silvestri'),
  ('Protótipo', array['Prototype']::text[], 'Prototipação', 'Simulação de um produto ou fluxo usada para testar ideias antes de construir. Pode ser de baixa ou alta fidelidade.', 'Telas no Figma ligadas entre si para testar se as pessoas conseguem marcar uma consulta.', 'Protótipo não é MVP: o protótipo testa a ideia, o MVP é um produto real e mínimo no mercado.', 'Silvestri + Google'),
  ('Protótipo Navegável', '{}'::text[], 'Prototipação', 'Protótipo com telas conectadas por interações clicáveis, que simula o uso real do produto para testes e apresentações.', 'Telas do Figma ligadas por cliques, usadas num teste de usabilidade remoto.', 'Navegável = dá para clicar e seguir de uma tela para outra.', null),
  ('Proximidade', array['Proximity', 'Lei da proximidade']::text[], 'Design Visual', 'Princípio da Gestalt: elementos próximos são percebidos como um grupo.', 'O rótulo ''E-mail'' colado no campo de e-mail, e mais distante do campo de senha.', 'O espaço entre grupos deve ser claramente maior que o espaço dentro de cada grupo.', 'Google'),
  ('Público-alvo', array['Target audience']::text[], 'Estratégia', 'Grupo de pessoas que o produto quer atingir, descrito por características gerais como idade, região ou ocupação.', '''Arquitetas de 25 a 40 anos em capitais'' é um público-alvo; ''Marina, que perde tempo procurando fornecedores'' é uma persona.', 'O público-alvo diz quem; a persona explica por quê e como essas pessoas agem.', 'Silvestri'),
  ('Região comum', array['Common region']::text[], 'Design Visual', 'Princípio da Gestalt: elementos dentro de uma mesma área delimitada são percebidos como um grupo.', 'Foto, nome e preço dentro do mesmo card são lidos como um único produto.', 'Use bordas ou fundos para agrupar quando o espaçamento sozinho não for suficiente.', 'Google'),
  ('Retrospectiva', array['Retrospective', 'Retro']::text[], 'Times & Métodos', 'Reunião no fim de uma sprint ou projeto para o time discutir o que funcionou, o que não funcionou e o que mudar.', 'Formato simples: ''o que manter, o que parar, o que começar''.', 'Saia da retro com no máximo 1 a 3 ações concretas, com responsável.', 'Google'),
  ('Roadmap', '{}'::text[], 'Estratégia', 'Plano visual que comunica a direção do produto ao longo do tempo, com temas, objetivos e prioridades, sem prometer datas exatas de cada entrega.', 'Agora: checkout. Próximo: assinaturas. Depois: marketplace.', 'Comunica direção e prioridades, não um cronograma de entregas.', null),
  ('ROI', array['Retorno sobre investimento', 'Return on investment']::text[], 'Estratégia', 'Indicador que compara o ganho obtido com o valor investido: (ganho − investimento) ÷ investimento.', 'Um redesign de R$ 50 mil que reduz chamados no suporte e economiza R$ 150 mil tem ROI de 200%.', 'Para defender pesquisa e design, traduza o resultado em números que a liderança acompanha.', 'Silvestri'),
  ('Scope creep', array['Aumento de escopo']::text[], 'Times & Métodos', 'Crescimento gradual e não planejado do escopo de um projeto, até ele ficar muito maior que o combinado.', '''Já que vamos mexer no cadastro, dá para incluir login social, foto de perfil e convite de amigos?''', 'Registre o escopo por escrito e trate cada pedido novo como uma troca: o que sai para isso entrar?', 'Google'),
  ('Screener', array['Screener survey', 'Questionário de recrutamento', 'Filtro de recrutamento']::text[], 'Pesquisa', 'Questionário usado para selecionar participantes que se encaixam nos critérios da pesquisa.', '''Você pedalou na cidade nos últimos 30 dias?'' — quem responde não fica de fora do estudo sobre ciclistas.', 'Não deixe óbvio o perfil desejado, senão as pessoas respondem para serem escolhidas.', 'Google'),
  ('Scrum', '{}'::text[], 'Times & Métodos', 'Framework ágil organizado em sprints, com papéis (Product Owner, Scrum Master, desenvolvedores) e eventos fixos como planning, daily, review e retrospectiva.', 'Um time que planeja a cada 2 semanas, faz daily de 15 minutos e encerra com review e retro segue o Scrum.', 'Scrum não é ''semelhante ao ágil'': é um framework dentro da abordagem ágil.', 'Silvestri'),
  ('SEO', array['Search Engine Optimization', 'Otimização para buscadores']::text[], 'Estratégia', 'Práticas para um conteúdo aparecer melhor em buscadores como o Google, envolvendo estrutura, texto e desempenho da página.', 'Usar títulos claros e a palavra que as pessoas realmente buscam (''aluguel de bike'') em vez de um nome criativo.', 'Boa parte do SEO coincide com boa UX: conteúdo claro, rápido e bem estruturado.', 'Silvestri'),
  ('Similaridade', array['Similarity', 'Lei da similaridade']::text[], 'Design Visual', 'Princípio da Gestalt: elementos com aparência parecida são percebidos como relacionados.', 'Todos os links em azul sublinhado são entendidos como clicáveis.', 'Se dois elementos fazem coisas diferentes, eles não devem ter a mesma aparência.', 'Google'),
  ('Sitemap', array['Mapa do site']::text[], 'Arquitetura da Informação', 'Diagrama hierárquico com todas as páginas de um site ou app e as relações entre elas.', 'Uma árvore com Início no topo e, abaixo, Produtos, Sobre, Blog e Contato.', 'Mapa do site: todas as páginas e como se ligam.', null),
  ('Sprint', '{}'::text[], 'Times & Métodos', 'Período fixo, geralmente de 1 a 4 semanas, em que o time se compromete a entregar um conjunto de itens do backlog.', 'Na sprint de 2 semanas, o time entrega o novo filtro de busca.', 'Não confunda com Design Sprint, que é um método de 5 dias para validar uma ideia.', 'Silvestri'),
  ('Sprint Review', array['Revisão da sprint']::text[], 'Times & Métodos', 'Reunião no fim da sprint em que o time mostra o que foi entregue e recebe feedback de stakeholders.', 'O time demonstra o novo filtro de busca funcionando para produto e atendimento.', 'É sobre o produto entregue; a conversa sobre o processo do time acontece na retrospectiva.', 'Silvestri'),
  ('Stakeholder', array['Partes interessadas', 'Project stakeholders']::text[], 'Estratégia', 'Qualquer pessoa ou grupo com interesse ou influência no projeto, como líderes, times internos, clientes ou parceiros.', 'O time jurídico precisa aprovar o novo fluxo de cadastro antes do lançamento.', 'Quem tem algo em jogo (stake) no resultado.', null),
  ('Storyboard', array['Big picture storyboard', 'Close-up storyboard']::text[], 'Prototipação', 'Sequência de quadros ilustrados que conta como uma pessoa usa o produto num contexto real, do problema à solução.', 'Seis quadros: a pessoa perde o ônibus, abre o app, vê o próximo horário e chega a tempo.', 'Como uma história em quadrinhos: contexto antes da interface.', null),
  ('Survey', array['Questionário', 'Surveys', 'Pesquisa por questionário']::text[], 'Pesquisa', 'Questionário aplicado a muitas pessoas para medir opiniões ou comportamentos, geralmente com perguntas fechadas.', 'Enviar 10 perguntas para 300 clientes para saber com que frequência usam o app.', 'Survey mostra ''quanto'' e ''quantos''; para entender ''por quê'', combine com entrevistas.', 'Silvestri + Google'),
  ('SUS', array['System Usability Scale', 'Escala SUS']::text[], 'Pesquisa', 'System Usability Scale: questionário de dez afirmações que gera uma pontuação de 0 a 100 para a usabilidade percebida de um sistema.', 'Ao fim de um teste, cada participante responde às dez afirmações; a média dá 72.', 'Acima de 68 é considerado acima da média.', null),
  ('T-shaped designer', array['Designer em T']::text[], 'Times & Métodos', 'Profissional com profundidade em uma área (a haste do T) e conhecimento amplo em várias outras (a barra do T).', 'Uma designer especialista em pesquisa que também entende de interface, dados e negócio.', 'Use para se posicionar: qual é a sua especialidade, e quais áreas você conhece bem o suficiente para colaborar?', 'Google'),
  ('Taxa de conversão', array['Conversion rate']::text[], 'Estratégia', 'Percentual de pessoas que realizam a ação esperada em relação ao total que poderia realizá-la.', '1.000 visitas na página e 30 compras: taxa de conversão de 3%.', 'Defina com o time qual ação é a ''conversão'' antes de medir.', 'Google'),
  ('Taxa de erro', array['User error rates', 'Error rate']::text[], 'Pesquisa', 'Frequência com que os usuários cometem erros ao realizar uma tarefa.', '3 de cada 10 pessoas preenchem a data de nascimento no formato errado.', 'Erro frequente é sinal de problema de design, não de usuário desatento.', 'Google'),
  ('Taxonomia', '{}'::text[], 'Arquitetura da Informação', 'Sistema de classificação que organiza conteúdos em categorias e subcategorias com nomes consistentes.', 'Num e-commerce de moda: Feminino › Roupas › Vestidos › Midi.', 'Taxonomia nomeia e classifica; navegação é como se chega lá.', null),
  ('Tecnologia assistiva', array['Assistive technology']::text[], 'Interação', 'Recursos, equipamentos ou softwares que ampliam a autonomia de pessoas com deficiência, como leitores de tela, controle por voz e ampliadores.', 'Uma pessoa com mobilidade reduzida navega por um site apenas com comandos de voz.', 'Teste seu produto com ao menos uma tecnologia assistiva: o leitor de tela do próprio celular já ajuda.', 'Google'),
  ('Tempo na tarefa', array['Time on task']::text[], 'Pesquisa', 'Quanto tempo uma pessoa leva para completar uma tarefa definida.', 'Remarcar uma consulta levava 2 minutos e 10 segundos; após o redesign, passou para 40 segundos.', 'Compare sempre a mesma tarefa, com o mesmo ponto de início e de fim.', 'Google'),
  ('Teste A/B', array['A/B test', 'Split test']::text[], 'Pesquisa', 'Experimento que compara duas versões de uma tela ou elemento com grupos diferentes de usuários para ver qual tem melhor desempenho numa métrica.', 'Metade dos visitantes vê o botão "Comprar agora" e metade vê "Adicionar ao carrinho".', 'Mude uma coisa por vez, ou você não sabe o que causou a diferença.', null),
  ('Teste de Usabilidade', array['Usability test', 'Usability study', 'Estudo de usabilidade']::text[], 'Pesquisa', 'Sessão em que pessoas reais tentam realizar tarefas num produto enquanto são observadas, para encontrar problemas de uso.', 'Cinco pessoas tentam agendar uma consulta no app enquanto o time observa onde elas travam.', 'Observe o que a pessoa faz, não só o que ela diz.', null),
  ('Texto alternativo', array['Alt text', 'Alternative text']::text[], 'Interação', 'Descrição em texto de uma imagem ou gráfico, lida por leitores de tela para quem não pode ver a imagem.', 'Em vez de ''imagem1.png'', usar ''Gráfico: vendas subiram 30% entre janeiro e março''.', 'Descreva a função da imagem no contexto. Imagens só decorativas devem ter alt vazio.', 'Google'),
  ('Think Aloud', '{}'::text[], 'Pesquisa', 'Protocolo em que a pessoa participante verbaliza o que pensa enquanto usa o produto, revelando expectativas e confusões.', '"Estou procurando o botão de pagar… achei que estaria aqui embaixo."', 'Pensar em voz alta revela expectativas que o clique sozinho esconde.', null),
  ('Tipografia', array['Typography', 'Typeface', 'Font', 'Fonte']::text[], 'Design Visual', 'A escolha e o arranjo das letras: família tipográfica, tamanho, peso, espaçamento e altura de linha.', 'Usar uma fonte mono para rótulos e uma serifada para textos longos, como neste glossário.', 'Duas famílias tipográficas costumam bastar. Mais que isso geralmente vira ruído.', 'Google'),
  ('Tree Testing', '{}'::text[], 'Arquitetura da Informação', 'Teste que avalia se as pessoas encontram itens numa estrutura de navegação em texto puro, sem layout visual. Valida a hierarquia.', 'Pedir que a pessoa encontre "segunda via do boleto" num menu só de texto.', 'Testa a árvore sem as folhas: estrutura sem layout.', null),
  ('Usabilidade', array['Usability']::text[], 'Interação', 'Quanto um produto permite que pessoas específicas atinjam objetivos com eficácia, eficiência e satisfação, num contexto de uso (ISO 9241-11).', 'Se 4 de 5 pessoas não encontram onde trocar a senha, a usabilidade dessa tarefa é baixa.', 'Usabilidade se mede em tarefas concretas, não com a pergunta ''você achou fácil?''.', 'Silvestri'),
  ('Usuário', array['User']::text[], 'Pesquisa', 'Pessoa que usa ou vai usar um produto ou serviço.', 'Num app de delivery há pelo menos três tipos de usuário: cliente, restaurante e entregador.', 'Raramente existe ''o usuário'': mapeie os diferentes grupos e suas necessidades.', 'Silvestri + Google'),
  ('UX', array['User Experience', 'Experiência do usuário']::text[], 'Estratégia', 'Tudo o que a pessoa percebe, sente e consegue fazer ao usar um produto ou serviço, antes, durante e depois do uso.', 'Um app bonito que exige 8 passos para pagar um boleto tem UX ruim.', 'UX não é só tela: inclui texto, tempo de resposta, suporte e até o e-mail de confirmação.', 'Silvestri + Google'),
  ('UX Designer', array['UX designers']::text[], 'Times & Métodos', 'Profissional que projeta a experiência de uso de um produto, da pesquisa e arquitetura aos fluxos e protótipos.', 'Conduzir entrevistas, desenhar o fluxo de cadastro e testá-lo antes de passar para o desenvolvimento.', 'Em muitas empresas, UX Designer e Product Designer são o mesmo cargo com nomes diferentes.', 'Silvestri + Google'),
  ('UX Engineer', array['UX engineers', 'Design engineer']::text[], 'Times & Métodos', 'Profissional que une design e código, construindo protótipos funcionais e componentes de interface.', 'Transformar o design system do Figma em componentes React prontos para o time usar.', 'É uma ponte valiosa entre design e desenvolvimento, comum em empresas maiores.', 'Google'),
  ('UX Researcher', array['UX researchers', 'Pesquisador de UX']::text[], 'Times & Métodos', 'Profissional especializado em planejar, conduzir e analisar pesquisas com usuários.', 'Desenhar o estudo, recrutar participantes, conduzir entrevistas e transformar os achados em recomendações.', 'Em times sem researcher, a pesquisa costuma ficar com o designer; vale dominar o básico.', 'Google'),
  ('UX Writing', array['UX writer', 'UX writers', 'Microcopy']::text[], 'Interação', 'Escrita dos textos da interface (botões, mensagens de erro, instruções) para orientar o usuário com clareza.', 'Trocar ''Erro 403'' por ''Sua sessão expirou. Entre de novo para continuar.''', 'Bom UX Writing é curto, específico e diz o que fazer em seguida.', 'Silvestri + Google'),
  ('UX/UI Designer', '{}'::text[], 'Times & Métodos', 'Profissional que acumula experiência (fluxos, pesquisa, estrutura) e interface (visual, componentes, layout).', 'Desenhar o fluxo de onboarding e também as telas finais com o design system.', 'É um título comum em vagas de empresas menores, onde uma pessoa cobre várias funções.', 'Silvestri'),
  ('Viés cognitivo', array['Bias', 'Viés']::text[], 'Pesquisa', 'Tendência sistemática de julgar ou decidir com base em atalhos mentais, e não só em evidências.', 'Achar que todos os usuários pensam como você porque o time é parecido com você.', 'Todo mundo tem vieses. O objetivo é reconhecê-los e criar processos que os reduzam.', 'Google'),
  ('Viés de confirmação', array['Confirmation bias']::text[], 'Pesquisa', 'Tendência a buscar e valorizar informações que confirmam o que já acreditamos, ignorando o que contradiz.', 'Lembrar só do participante que elogiou sua ideia e esquecer os três que travaram.', 'Antes do teste, escreva o que provaria que sua hipótese está errada.', 'Google'),
  ('Viés de desejabilidade social', array['Social desirability bias']::text[], 'Pesquisa', 'Tendência dos participantes de responder o que parece socialmente aceito, e não o que realmente fazem.', 'Todos dizem que leem os termos de uso, mas ninguém lê.', 'Pergunte sobre comportamentos passados concretos (''a última vez que...''), não sobre hábitos ideais.', 'Google'),
  ('Viés de falso consenso', array['False consensus bias']::text[], 'Pesquisa', 'Tendência a supor que as outras pessoas pensam e agem como nós.', '''Todo mundo sabe que é só arrastar para o lado'' — só porque você sabe.', 'Quando alguém do time disser ''é óbvio'', é um bom sinal para testar.', 'Google'),
  ('Viés de primazia', array['Primacy bias']::text[], 'Pesquisa', 'Tendência a lembrar mais e dar mais peso às primeiras informações recebidas.', 'Depois de 6 entrevistas, a primeira é a que mais influencia o relatório.', 'Anote tudo logo após cada sessão e sintetize olhando as anotações, não a memória.', 'Google'),
  ('Viés de recência', array['Recency bias']::text[], 'Pesquisa', 'Tendência a dar mais peso às informações mais recentes.', 'O último participante do dia reclamou do preço, e de repente ''preço'' vira o maior problema do relatório.', 'Use uma matriz ou um diagrama de afinidade para comparar todas as sessões com o mesmo peso.', 'Google'),
  ('Viés implícito', array['Implicit bias', 'Viés inconsciente']::text[], 'Pesquisa', 'Associações e estereótipos inconscientes que influenciam decisões sem que a pessoa perceba.', 'Usar sempre homens nas ilustrações de ''gestor'' e mulheres nas de ''assistente''.', 'Revise personas, imagens e exemplos com olhar crítico e, se possível, com pessoas diversas.', 'Google'),
  ('Waterfall', array['Cascata', 'Modelo cascata']::text[], 'Times & Métodos', 'Modelo em que as etapas acontecem em sequência rígida (requisitos, design, desenvolvimento, teste, entrega), cada uma começando quando a anterior termina.', 'Seis meses de especificação antes de escrever a primeira linha de código.', 'O risco é descobrir problemas só no fim, quando mudar custa muito caro.', 'Silvestri'),
  ('Wayfinding', '{}'::text[], 'Arquitetura da Informação', 'Conjunto de pistas que ajudam a pessoa a saber onde está, para onde pode ir e como voltar dentro de um produto.', 'O item ativo destacado no menu e o título da página dizem onde a pessoa está.', 'Vem da sinalização de aeroportos e hospitais.', null),
  ('WCAG', array['Web Content Accessibility Guidelines', 'Diretrizes de acessibilidade']::text[], 'Interação', 'Diretrizes do W3C para tornar conteúdo web acessível, organizadas em níveis A, AA e AAA. A versão atual é a 2.2.', 'O nível AA exige contraste mínimo de 4,5:1 para texto normal.', 'AA é o nível que a maioria das leis e empresas adota como meta.', 'Google'),
  ('Wireframe', array['Esqueleto de tela']::text[], 'Prototipação', 'Esqueleto de uma tela que define estrutura, hierarquia e posição dos elementos, sem acabamento visual.', 'Caixas cinza indicando onde ficam o logo, a busca, os filtros e a lista de produtos.', 'Esqueleto: estrutura antes da pele.', null)
